def save_prediction_results(self, filename: str, per_agent_filename: Optional[str] = None) -> None:
    try:
        df = pd.DataFrame(self.observables)
        pred_df = df[df["is_prediction_window"] == 1].copy()
        pred_df.to_csv(filename, index=False)
        if per_agent_filename is not None:
            s, e = self.prediction_window
            if s is not None and e is not None:
                days = list(range(s, e + 1))
                rows = []
                for d in days:
                    arr = self.adoption_state[d, :]
                    for i, aid in enumerate(self.agent_ids):
                        rows.append({"day": d, "agent_id": aid, "wearing_mask": int(arr[i])})
                pd.DataFrame(rows).to_csv(per_agent_filename, index=False)
        print(f"Prediction window results saved to {filename}")
    except Exception as e:
        print(f"Error saving prediction results to {filename}: {e}")
